import Foundation
import SwxCore
import SwxManifest
import SwxStore
import SwxSystem

/// `swx xcode generate`: an `.xcodeproj` for a package's AppleProductTypes apps, for when an app
/// outgrows a package (extensions, entitlements, custom build phases). Built from the manifest
/// as an XcodeGen spec, generated by XcodeGen (run through `swx tool run`).
public struct XcodeProjectGenerator: Sendable {
    private let options: WorkspaceOptions
    private let packageDirectory: URL

    private enum Spec {
        static let fileName = ".swx-xcodegen.json"
        static let sourcesDirectory = "Sources"
        static let applicationType = "application"
        static let libraryType = "library.static"
        static let iOS = "iOS"
        static let projectExtension = "xcodeproj"
        static let generationCache = "xcodegen.cache"
    }

    /// How the spec names the package's files: relative to the package (a project generated next
    /// to it), or absolute (a project generated elsewhere).
    enum SpecPaths {
        case relative
        case absolute
    }

    private enum Setting {
        static let bundleIdentifier = "PRODUCT_BUNDLE_IDENTIFIER"
        static let team = "DEVELOPMENT_TEAM"
        static let marketingVersion = "MARKETING_VERSION"
        static let buildVersion = "CURRENT_PROJECT_VERSION"
        static let generateInfoPlist = "GENERATE_INFOPLIST_FILE"
        static let launchScreen = "INFOPLIST_KEY_UILaunchScreen_Generation"
        static let sceneManifest = "INFOPLIST_KEY_UIApplicationSceneManifest_Generation"
        static let deviceFamily = "TARGETED_DEVICE_FAMILY"
        static let orientations = "INFOPLIST_KEY_UISupportedInterfaceOrientations"
        static let padOrientations = "INFOPLIST_KEY_UISupportedInterfaceOrientations_iPad"
        static let swiftVersion = "SWIFT_VERSION"
        static let yes = "YES"
    }

    /// `TARGETED_DEVICE_FAMILY` codes.
    private static let deviceFamilyCodes = ["phone": "1", "pad": "2"]
    private static let orientationKeys = [
        "portrait": "UIInterfaceOrientationPortrait",
        "portraitUpsideDown": "UIInterfaceOrientationPortraitUpsideDown",
        "landscapeLeft": "UIInterfaceOrientationLandscapeLeft",
        "landscapeRight": "UIInterfaceOrientationLandscapeRight",
    ]
    private static let xcodeGen = "xcodegen"
    private static let swift6LanguageVersion = "6.0"
    private static let swift5LanguageVersion = "5.0"

    /// Tools 6 manifests build in the Swift 6 language mode, as SwiftPM builds them.
    private static func swiftVersion(_ toolsVersion: ToolsVersion) -> String {
        toolsVersion >= Self.swift6 ? Self.swift6LanguageVersion : Self.swift5LanguageVersion
    }
    private static let swift6 = ToolsVersion(6, 0)

    public init(options: WorkspaceOptions, packageDirectory: URL) {
        self.options = options
        self.packageDirectory = packageDirectory
    }

    /// The deployment target of generated targets when none is given.
    public static let defaultDeploymentTarget = "17.0"

    /// Writes `<package>/<Name>.xcodeproj` and returns it. Without an explicit deployment target,
    /// the package's own `platforms:` minimum is used, then the default.
    public func generate(deploymentTarget explicit: String?) async throws -> URL {
        let manifest = try await self.loadManifest()
        let minimums = self.loadPlatformMinimums()
        let spec = try Self.spec(
            for: manifest,
            packageDirectory: self.packageDirectory,
            deploymentTarget: Self.iOSDeploymentTarget(explicit: explicit, minimums: minimums),
            paths: .relative,
            overlay: try self.loadOverlay(manifest),
            platforms: minimums
        )
        return try await self.runXcodeGen(spec: spec, name: manifest.name, specDirectory: self.packageDirectory, projectDirectory: self.packageDirectory, cache: .none)
    }

    /// A project for building and running the app product `product` that lives in `directory`
    /// (under `.build`), so the package itself is left untouched; `nil` when `product` isn't an app.
    /// XcodeGen's cache skips regenerating when neither the spec nor the source files changed.
    func generatePrivateProject(for product: String, in directory: URL) async throws -> URL? {
        let manifest = try await self.loadManifest()
        guard manifest.products.contains(where: { $0.name == product && $0.kind == .application }) else { return nil }
        let minimums = self.loadPlatformMinimums()
        let spec = try Self.spec(
            for: manifest,
            packageDirectory: self.packageDirectory,
            deploymentTarget: Self.iOSDeploymentTarget(explicit: nil, minimums: minimums),
            paths: .absolute,
            overlay: try self.loadOverlay(manifest),
            platforms: minimums
        )
        try FileSystem.createDirectory(directory)
        return try await self.runXcodeGen(spec: spec, name: manifest.name, specDirectory: directory, projectDirectory: directory, cache: .useCache)
    }

    /// The package's manifest, as project generation reads it.
    func manifest() async throws -> Manifest {
        try await self.loadManifest()
    }

    private func loadManifest() async throws -> Manifest {
        let store = self.options.cacheDirectory.map(Store.init(root:)) ?? Store.default()
        let toolchain = try await Toolchain.detect(store: store)
        let loader = ManifestLoader(store: store, toolchain: toolchain, maximumConcurrency: self.options.maximumConcurrency)
        return try await loader.load(packageAt: self.packageDirectory)
    }

    /// The manifest's declared OS minimums; none when it can't be read.
    private func loadPlatformMinimums() -> PlatformMinimums {
        let file = self.packageDirectory.appendingPathComponent(WellKnownFile.manifest)
        guard let data = FileSystem.readIfPresent(file) else { return .none }
        return PlatformMinimums.read(manifestSource: String(decoding: data, as: UTF8.self))
    }

    /// An explicit target wins, then the package's `platforms:` minimum, then the default.
    static func iOSDeploymentTarget(explicit: String?, minimums: PlatformMinimums) -> String {
        explicit ?? minimums.iOS ?? Self.defaultDeploymentTarget
    }

    /// `swx-xcode.json` next to the manifest, or no overlay when there is none.
    private func loadOverlay(_ manifest: Manifest) throws -> XcodeOverlay {
        let file = self.packageDirectory.appendingPathComponent(XcodeOverlay.fileName)
        guard let data = FileSystem.readIfPresent(file) else { return .none }
        return try XcodeOverlay.parse(data, manifest: manifest)
    }

    /// Whether XcodeGen may skip a generation whose inputs didn't change.
    private enum GenerationCache {
        case none
        case useCache
    }

    private func runXcodeGen(spec: [String: Any], name: String, specDirectory: URL, projectDirectory: URL, cache: GenerationCache) async throws -> URL {
        // The spec sits in its directory only while XcodeGen reads it.
        let specFile = specDirectory.appendingPathComponent(Spec.fileName)
        try FileSystem.writeAtomically(try JSONSerialization.data(withJSONObject: spec, options: [.prettyPrinted, .sortedKeys]), to: specFile)
        defer { try? FileManager.default.removeItem(at: specFile) }

        // XcodeGen, built and cached like any `swx tool run` tool.
        let tool = try await ToolRunner(options: self.options).prepare(ToolRunner.aliases[Self.xcodeGen] ?? Self.xcodeGen, executable: Self.xcodeGen)
        var arguments = [tool.executable.path, "generate", "--spec", specFile.path, "--project", projectDirectory.path, "--quiet"]
        if cache == .useCache {
            arguments += ["--use-cache", "--cache-path", specDirectory.appendingPathComponent(Spec.generationCache).path]
        }
        let result = try await ProcessRunner.run(arguments, exitPolicy: .allowFailure)
        guard result.succeeded else {
            throw WorkspaceError(description: "XcodeGen failed:\n\(result.output)\(result.errorOutput)")
        }
        return projectDirectory.appendingPathComponent(name).appendingPathExtension(Spec.projectExtension)
    }

    // MARK: Spec (pure)

    static func spec(
        for manifest: Manifest,
        packageDirectory: URL,
        deploymentTarget: String,
        paths: SpecPaths = .relative,
        overlay: XcodeOverlay = .none,
        platforms: PlatformMinimums = .none
    ) throws -> [String: Any] {
        let applications = manifest.products.filter { $0.kind == .application }
        guard !applications.isEmpty else {
            throw WorkspaceError(description: "\(manifest.name) declares no application products (.iOSApplication)")
        }

        var packages: [String: [String: String]] = [:]
        var targets: [String: Any] = [:]
        var libraries = LibraryCollector()
        let local = LocalProducts(manifest: manifest, packageDirectory: packageDirectory, paths: paths)
        for application in applications {
            // The app's own targets become one application target…
            let appDependencies = try Self.dependencies(of: application.targets, in: manifest, packageDirectory: packageDirectory, paths: paths, local: local, packages: &packages)
            var app: [String: Any] = [
                "type": Spec.applicationType,
                "platform": Spec.iOS,
                "sources": try Self.sources(application.targets, packageDirectory: packageDirectory, paths: paths),
                "dependencies": appDependencies.entries.map { $0 as [String: Any] } + Self.embeddings(in: application.name, overlay: overlay),
                "settings": ["base": Self.settings(application.application, toolsVersion: manifest.parsedToolsVersion)],
            ]
            if let appOverlay = overlay.applications[application.name] {
                Self.addPlists(to: &app, target: application.name, entitlements: appOverlay.entitlements, infoPlist: appOverlay.infoPlist)
            }
            targets[application.name] = app

            // …and the internal targets it imports become static libraries, keeping their module names
            // (unless a library product of the package vends them: those link as package products).
            libraries.add(appDependencies.internalTargets, for: .iOS, excluding: application.targets)
        }

        // Overlay targets (extensions, watch apps) are built from SwiftPM targets' sources like apps.
        for extra in overlay.targets {
            guard let application = applications.first(where: { $0.name == extra.embedIn }) else { continue }

            let dependencies = try Self.dependencies(of: extra.sources, in: manifest, packageDirectory: packageDirectory, paths: paths, local: local, packages: &packages)
            targets[extra.name] = try Self.extraTarget(extra, application: application, manifest: manifest, packageDirectory: packageDirectory, paths: paths, dependencies: dependencies.entries)
            libraries.add(dependencies.internalTargets, for: extra.kind.platform, excluding: extra.sources)
        }

        // Libraries are emitted last: only now is every platform that links them known.
        while let library = libraries.next() {
            let (name, platforms) = library
            let dependencies = try Self.dependencies(of: [name], in: manifest, packageDirectory: packageDirectory, paths: paths, local: local, packages: &packages)
            var libraryTarget: [String: Any] = [
                "type": Spec.libraryType,
                "sources": try Self.sources([name], packageDirectory: packageDirectory, paths: paths),
                "dependencies": dependencies.entries,
                "settings": ["base": [Setting.swiftVersion: Self.swiftVersion(manifest.parsedToolsVersion)]],
            ]
            libraryTarget.merge(Self.platformKeys(platforms)) { _, new in new }
            targets[name] = libraryTarget
            libraries.add(dependencies.internalTargets, for: platforms)
        }

        return [
            "name": manifest.name,
            "options": ["deploymentTarget": Self.deploymentTargets(iOS: deploymentTarget, overlay: overlay, platforms: platforms)],
            "packages": packages,
            "targets": targets,
            "schemes": Self.schemes(for: applications.map(\.name)),
        ]
    }

    // MARK: Schemes (pure)

    /// One shared scheme per app, building the app target (and so everything it embeds).
    static func schemes(for applications: [String]) -> [String: Any] {
        Dictionary(uniqueKeysWithValues: applications.map { application in
            (Self.schemeName(for: application), ["build": ["targets": [application: "all"]]] as [String: Any])
        })
    }

    static func schemeName(for application: String) -> String {
        application
    }

    // MARK: Overlay targets (pure)

    /// The platforms an XcodeGen target is built for.
    enum TargetPlatform: String, Sendable, Comparable {
        case iOS
        case watchOS

        static func < (lhs: Self, rhs: Self) -> Bool { lhs.rawValue < rhs.rawValue }
    }

    private enum Overlay {
        static let supportDirectory = "XcodeSupport"
        static let entitlementsExtension = "entitlements"
        static let infoPlistSuffix = "-Info.plist"
        static let appExtensionType = "app-extension"
        static let multiplatform = "auto"
        static let supportedDestinations = "supportedDestinations"
        static let watchContentsSubpath = "$(CONTENTS_FOLDER_PATH)/Watch"
        static let productsDirectory = "productsDirectory"
        static let extensionKey = "NSExtension"
        static let extensionPointKey = "NSExtensionPointIdentifier"
        static let widgetExtensionPoint = "com.apple.widgetkit-extension"
        static let watchApplicationKey = "WKApplication"
        static let companionSetting = "INFOPLIST_KEY_WKCompanionAppBundleIdentifier"
        static let displayNameSetting = "INFOPLIST_KEY_CFBundleDisplayName"
        /// watchOS apps embedded in iOS 17 apps.
        static let defaultWatchDeploymentTarget = "10.0"
        static let versionSeparator: Character = "."
    }

    /// The app's dependencies on the overlay targets it embeds: extensions go to PlugIns
    /// (XcodeGen's default), a watch app to `Watch/`.
    private static func embeddings(in application: String, overlay: XcodeOverlay) -> [[String: Any]] {
        overlay.targets.filter { $0.embedIn == application }.map { extra in
            switch extra.kind {
            case .widgetExtension:
                return ["target": extra.name, "embed": true]
            case .watchApp:
                return [
                    "target": extra.name,
                    "embed": true,
                    "copy": ["destination": Overlay.productsDirectory, "subpath": Overlay.watchContentsSubpath],
                ]
            }
        }
    }

    private static func extraTarget(
        _ extra: XcodeOverlay.ExtraTarget,
        application: Manifest.Product,
        manifest: Manifest,
        packageDirectory: URL,
        paths: SpecPaths,
        dependencies: [[String: String]]
    ) throws -> [String: Any] {
        // Versions and team follow the app: embedded bundles must match it.
        var settings = [
            Setting.bundleIdentifier: extra.bundleIdentifier,
            Setting.generateInfoPlist: Setting.yes,
            Setting.swiftVersion: Self.swiftVersion(manifest.parsedToolsVersion),
            Overlay.displayNameSetting: extra.name,
        ]
        settings[Setting.marketingVersion] = application.application?.displayVersion
        settings[Setting.buildVersion] = application.application?.bundleVersion
        if let team = application.application?.teamIdentifier, !team.isEmpty {
            settings[Setting.team] = team
        }

        // What each kind needs in its Info.plist and settings to be recognised as one.
        var infoPlist = extra.infoPlist
        let type: String
        switch extra.kind {
        case .widgetExtension:
            type = Overlay.appExtensionType
            infoPlist[Overlay.extensionKey] = infoPlist[Overlay.extensionKey]
                ?? .dictionary([Overlay.extensionPointKey: .string(Overlay.widgetExtensionPoint)])
        case .watchApp:
            type = Spec.applicationType
            settings[Overlay.companionSetting] = application.application?.bundleIdentifier
            infoPlist[Overlay.watchApplicationKey] = infoPlist[Overlay.watchApplicationKey] ?? .bool(true)
        }

        var target: [String: Any] = [
            "type": type,
            "platform": extra.kind.platform.rawValue,
            "sources": try Self.sources(extra.sources, packageDirectory: packageDirectory, paths: paths),
            "dependencies": dependencies,
            "settings": ["base": settings],
        ]
        if let deploymentTarget = extra.deploymentTarget {
            target["deploymentTarget"] = deploymentTarget
        }
        Self.addPlists(to: &target, target: extra.name, entitlements: extra.entitlements, infoPlist: infoPlist)
        return target
    }

    /// Entitlements and Info.plist entries, written by XcodeGen next to the project (it also points
    /// `CODE_SIGN_ENTITLEMENTS` / `INFOPLIST_FILE` at them; generated keys are merged by Xcode).
    private static func addPlists(to target: inout [String: Any], target name: String, entitlements: [String: XcodeOverlay.PlistValue], infoPlist: [String: XcodeOverlay.PlistValue]) {
        if !entitlements.isEmpty {
            target["entitlements"] = [
                "path": "\(Overlay.supportDirectory)/\(name).\(Overlay.entitlementsExtension)",
                "properties": entitlements.mapValues(\.json),
            ]
        }
        if !infoPlist.isEmpty {
            target["info"] = [
                "path": "\(Overlay.supportDirectory)/\(name)\(Overlay.infoPlistSuffix)",
                "properties": infoPlist.mapValues(\.json),
            ]
        }
    }

    /// A library linked from one platform keeps `platform: iOS` as before; one shared by the iOS
    /// app and the watch app is a single multiplatform target, so its module name stays the same.
    private static func platformKeys(_ platforms: Set<TargetPlatform>) -> [String: Any] {
        guard platforms.count > 1 else {
            return ["platform": (platforms.first ?? .iOS).rawValue]
        }
        return ["platform": Overlay.multiplatform, Overlay.supportedDestinations: platforms.sorted().map(\.rawValue)]
    }

    /// The project's deployment targets: iOS as asked, watchOS as low as any watch app needs
    /// (its own target, else the package's watchOS minimum, else the default).
    private static func deploymentTargets(iOS: String, overlay: XcodeOverlay, platforms: PlatformMinimums) -> [String: String] {
        var targets = [Spec.iOS: iOS]
        let watchApps = overlay.targets.filter { $0.kind == .watchApp }
        guard !watchApps.isEmpty else { return targets }

        let watchVersions = watchApps.map { $0.deploymentTarget ?? platforms.watchOS ?? Overlay.defaultWatchDeploymentTarget }
        targets[TargetPlatform.watchOS.rawValue] = watchVersions.min { Self.versionComponents($0).lexicographicallyPrecedes(Self.versionComponents($1)) }
        return targets
    }

    private static func versionComponents(_ version: String) -> [Int] {
        version.split(separator: Overlay.versionSeparator).compactMap { Int($0) }
    }

    /// Internal targets to emit as libraries, with every platform that links them, in discovery order.
    struct LibraryCollector {
        private var order: [String] = []
        private var platforms: [String: Set<TargetPlatform>] = [:]
        private var emitted: [String: Set<TargetPlatform>] = [:]
        private var excluded: Set<String> = []

        /// Records `names` as linked from `platform`; targets in `excluding` are an app's or
        /// extension's own sources, never libraries.
        mutating func add(_ names: [String], for platform: TargetPlatform, excluding own: [String] = []) {
            self.add(names, for: [platform], excluding: own)
        }

        mutating func add(_ names: [String], for platforms: Set<TargetPlatform>, excluding own: [String] = []) {
            self.excluded.formUnion(own)
            for name in names where !self.excluded.contains(name) {
                if self.platforms[name] == nil {
                    self.order.append(name)
                }
                self.platforms[name, default: []].formUnion(platforms)
            }
        }

        /// The next library whose platforms changed since it was last emitted (each library is
        /// re-emitted, with its dependencies, when another platform turns out to need it).
        mutating func next() -> (String, Set<TargetPlatform>)? {
            for name in self.order {
                let platforms = self.platforms[name] ?? []
                guard self.emitted[name] != platforms, !self.excluded.contains(name) else { continue }
                self.emitted[name] = platforms
                return (name, platforms)
            }
            return nil
        }
    }

    /// The package's own library products. Xcode builds a target it links through one with full
    /// SwiftPM semantics (system-library modules, resources and `Bundle.module`, plugins), which a
    /// translated static library lacks.
    struct LocalProducts {
        /// The package's key in the spec's `packages`: its manifest name.
        let packageKey: String
        let packageEntry: [String: String]
        private let productByTarget: [String: String]

        /// The current directory, as XcodeGen resolves a relative package path (the spec's own).
        private static let currentDirectory = "."

        init(manifest: Manifest, packageDirectory: URL, paths: SpecPaths) {
            self.packageKey = manifest.name
            switch paths {
            case .relative:
                self.packageEntry = ["path": Self.currentDirectory]
            case .absolute:
                self.packageEntry = ["path": packageDirectory.standardizedFileURL.path]
            }

            // Each target links through the narrowest library product that vends it (fewest
            // targets, then name, so the choice is stable).
            let libraries = manifest.products
                .filter { $0.kind == .library }
                .sorted { ($0.targets.count, $0.name) < ($1.targets.count, $1.name) }
            var productByTarget: [String: String] = [:]
            for product in libraries {
                for target in product.targets where productByTarget[target] == nil {
                    productByTarget[target] = product.name
                }
            }
            self.productByTarget = productByTarget
        }

        func product(for target: String) -> String? {
            self.productByTarget[target]
        }
    }

    /// Sources must live in the default `Sources/<target>` layout.
    private static func sources(_ targets: [String], packageDirectory: URL, paths: SpecPaths) throws -> [[String: String]] {
        try targets.map { target in
            let directory = packageDirectory.appendingPathComponent(Spec.sourcesDirectory).appendingPathComponent(target)
            guard FileSystem.isDirectory(directory) else {
                throw WorkspaceError(description: "target \(target) is not in Sources/\(target); custom target paths are not supported")
            }
            switch paths {
            case .relative:
                return ["path": Spec.sourcesDirectory + "/" + target]
            case .absolute:
                return ["path": directory.path]
            }
        }
    }

    /// XcodeGen dependencies of `targets`: internal targets by name, external products by package.
    private static func dependencies(
        of targets: [String],
        in manifest: Manifest,
        packageDirectory: URL,
        paths: SpecPaths,
        local: LocalProducts,
        packages: inout [String: [String: String]]
    ) throws -> (entries: [[String: String]], internalTargets: [String]) {
        let targetNames = Set(manifest.targets.map(\.name))
        var entries: [[String: String]] = []
        var internalTargets: [String] = []

        // An internal target a library product vends links as that product; the rest are translated.
        func addInternal(_ name: String) {
            guard let product = local.product(for: name), !targets.contains(name) else {
                internalTargets.append(name)
                return
            }
            packages[local.packageKey] = local.packageEntry
            let entry = ["package": local.packageKey, "product": product]
            if !entries.contains(entry) {
                entries.append(entry)
            }
        }

        func addProduct(_ product: String, package packageName: String) throws {
            let (key, package) = try Self.package(named: packageName, in: manifest, packageDirectory: packageDirectory, paths: paths)
            packages[key] = package
            let entry = ["package": key, "product": product]
            if !entries.contains(entry) {
                entries.append(entry)
            }
        }

        for name in targets {
            guard let target = manifest.targets.first(where: { $0.name == name }) else {
                throw WorkspaceError(description: "unknown target \(name)")
            }
            for dependency in target.dependencies {
                switch dependency {
                case .target(let name, _):
                    addInternal(name)
                case .byName(let name, _) where targetNames.contains(name):
                    addInternal(name)
                case .byName(let name, _), .product(let name, nil, _):
                    // A product named like its package (`.byName("Alamofire")`).
                    try addProduct(name, package: name)
                case .product(let name, let package?, _):
                    try addProduct(name, package: package)
                }
            }
        }
        for name in internalTargets where !targets.contains(name) {
            entries.append(["target": name])
        }
        return (entries, internalTargets.filter { !targets.contains($0) })
    }

    /// The XcodeGen package entry for a dependency, keyed by its reference name.
    private static func package(named name: String, in manifest: Manifest, packageDirectory: URL, paths: SpecPaths) throws -> (String, [String: String]) {
        guard let dependency = manifest.dependencies.first(where: { $0.referenceName.lowercased() == name.lowercased() || $0.identity.lowercased() == name.lowercased() }) else {
            throw WorkspaceError(description: "no dependency provides package '\(name)'")
        }

        var entry: [String: String] = [:]
        switch dependency.location {
        case .remote(let url):
            entry["url"] = url
        case .localSourceControl(let path), .local(let path):
            entry["path"] = paths == .absolute ? URL(fileURLWithPath: path, relativeTo: URL(fileURLWithPath: packageDirectory.path, isDirectory: true)).standardizedFileURL.path : path
        case .registry(let identity):
            throw WorkspaceError(description: "registry dependency \(identity) can't be added to an Xcode project; Xcode only references packages by URL or path")
        }

        switch dependency.requirement {
        case .range(let lower, let upper):
            if let lowerVersion = Version(lower), Version(upper) == Version(lowerVersion.major + 1, 0, 0) {
                entry["from"] = lower
            } else {
                entry["minVersion"] = lower
                entry["maxVersion"] = upper
            }
        case .exact(let version):
            entry["exactVersion"] = version
        case .branch(let branch):
            entry["branch"] = branch
        case .revision(let revision):
            entry["revision"] = revision
        case .none:
            break
        }
        return (dependency.referenceName, entry)
    }

    /// Build settings from `.iOSApplication(…)`: Info.plist keys are generated, not written.
    private static func settings(_ application: Manifest.Product.ApplicationSettings?, toolsVersion: ToolsVersion) -> [String: String] {
        var settings = [
            Setting.generateInfoPlist: Setting.yes,
            Setting.launchScreen: Setting.yes,
            Setting.sceneManifest: Setting.yes,
            Setting.swiftVersion: Self.swiftVersion(toolsVersion),
        ]
        guard let application else { return settings }

        settings[Setting.bundleIdentifier] = application.bundleIdentifier
        settings[Setting.marketingVersion] = application.displayVersion
        settings[Setting.buildVersion] = application.bundleVersion
        if let team = application.teamIdentifier, !team.isEmpty {
            settings[Setting.team] = team
        }
        let families = application.deviceFamilies.compactMap { Self.deviceFamilyCodes[$0] }
        if !families.isEmpty {
            settings[Setting.deviceFamily] = families.joined(separator: ",")
        }
        let orientations = application.interfaceOrientations.compactMap { Self.orientationKeys[$0] }
        if !orientations.isEmpty {
            settings[Setting.orientations] = orientations.joined(separator: " ")
            settings[Setting.padOrientations] = orientations.joined(separator: " ")
        }
        return settings
    }
}
